package org.brightstats.desktop;
import java.util.*;import java.nio.file.*;import com.google.gson.*;import org.brightstats.data.*;import org.brightstats.stats.*;
public final class ExampleChecks{
 public static void main(String[] args)throws Exception{var examples=StudioExamples.all();int checks=0;for(int i=0;i<examples.size();i++){var project=examples.get(i).project();Gson gson=new Gson();var names=project.getAsJsonArray("columnNames").asList().stream().map(JsonElement::getAsString).toList();double[][] values=gson.fromJson(project.get("observations"),double[][].class);ImportHistory.verify(project.getAsJsonObject("dataPreparation"),names,values);checks++;if(!ImportHistory.read(project.getAsJsonObject("dataPreparation")).sourceName().endsWith("seed "+(20261105+i)))throw new AssertionError("Synthetic provenance seed differs from its generator");checks++;if(!project.equals(StudioExamples.all().get(i).project()))throw new AssertionError("Example generation not reproducible");checks++;if(i==0){var settings=gson.fromJson(project.get("semOptions"),SemDialog.Settings.class);double[][] raw=MissingInput.originalAll(project.getAsJsonObject("dataPreparation"),names,values);if(Arrays.stream(raw).flatMapToDouble(Arrays::stream).noneMatch(Double::isNaN))throw new AssertionError("Missingness example lost source NaNs");var fit=FimlSem.fit(raw,settings.customModel(),FimlSem.Options.defaults());if(!fit.converged()||!fit.locallyIdentified()||fit.boundary())throw new AssertionError("Missingness teaching model is not regular");checks+=2;}else if(i==1){var settings=gson.fromJson(project.get("ordinalSettings"),OrdinalDialog.Settings.class);var history=ImportHistory.read(project.getAsJsonObject("dataPreparation"));var prepared=OrdinalData.prepare(history.raw(),history.settings(),history.definitions(),settings.specification());var model=OrdinalSem.reflective(names,settings.blocks(),settings.edges());var fit=OrdinalSem.fit(prepared.codes(),names,settings.specification().orderedLevels(),model.model(),settings.options());if(!fit.converged()||!fit.locallyIdentified()||fit.boundary())throw new AssertionError("Ordinal teaching model is not regular");checks++;}else{var settings=gson.fromJson(project.get("clusterSettings"),ClusterDialog.Settings.class);var source=ClusterData.select(project.getAsJsonObject("dataPreparation"),names,values,settings.sourceColumn(),settings.sourceName(),settings.marginalModel(),false);var fit=ClusterSem.fit(source.data(),source.ids(),settings.marginalModel(),settings.options(),null);if(fit.informativeClusters()!=24)throw new AssertionError("Cluster example groups changed");checks++;}}JsonObject receipt=new JsonObject();receipt.addProperty("state","passed");receipt.addProperty("checks",checks);System.out.println(receipt);if(args.length>0){Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("example-receipt.json"),receipt.toString());}}
}
